INSERT INTO _emdash_seo (collection, content_id, seo_title, seo_description, seo_image, seo_canonical, seo_no_index, created_at, updated_at) VALUES ('posts', '01M59K4K2Z3MFADWNXQA39GAEK', '【檳城 CityWalk 漫步隨筆】逃離觀光客打卡！喬治市散步、行前避坑與台馬路權觀察', '拒絕走馬看花的老套行程！深度記錄馬來西亞檳城喬治市的真實步行生活，從街區古建築的人文溫度，到台馬行人路權的犀利對比，開啟一場不討好觀光客的南洋深度漫遊。', NULL, 'https://flavorinsight.com/posts/penang-walking-notes', 0, datetime('now'), datetime('now')) ON CONFLICT (collection, content_id) DO UPDATE SET seo_title = excluded.seo_title, seo_description = excluded.seo_description, seo_canonical = excluded.seo_canonical, updated_at = datetime('now');
INSERT INTO _emdash_seo (collection, content_id, seo_title, seo_description, seo_image, seo_canonical, seo_no_index, created_at, updated_at) VALUES ('posts', '01M59K4QNWK00Z8SWY1RRYDM6Y', '【馬來西亞火車攻略】KTM ETS Platinum 豪華列車搭乘實測：KTMB 訂票避坑與怡保一日遊', '馬來西亞火車怎麼搭？實測 KTM ETS Platinum 豪華白金商務車廂，體驗飛機艙座等級服務與極致平穩行程。內含 KTMB App 購票眉角與檳城至怡保一日遊鐵道自由行心得。', NULL, 'https://flavorinsight.com/posts/malaysia-ktm-train-guide', 0, datetime('now'), datetime('now')) ON CONFLICT (collection, content_id) DO UPDATE SET seo_title = excluded.seo_title, seo_description = excluded.seo_description, seo_canonical = excluded.seo_canonical, updated_at = datetime('now');
INSERT INTO _emdash_seo (collection, content_id, seo_title, seo_description, seo_image, seo_canonical, seo_no_index, created_at, updated_at) VALUES ('posts', '01M59K4VXSA8VYD6TRHTETHB09', '【大馬茶室生存指南】把茶水小販當侍酒師！虎咬獅奇妙搭配與被在地人熱情餵食的南洋人情', '在大馬熱天徒步如何生存？學會把茶室阿伯當成侍酒師，解鎖炒粿條配涼茶、福建麵搭虎咬獅的在地喝法！記錄當你真誠熱愛美食時，大馬人像「怕你餓的台灣阿嬤」般熱情餵食的溫暖實錄。', NULL, 'https://flavorinsight.com/posts/malaysia-street-hospitality', 0, datetime('now'), datetime('now')) ON CONFLICT (collection, content_id) DO UPDATE SET seo_title = excluded.seo_title, seo_description = excluded.seo_description, seo_canonical = excluded.seo_canonical, updated_at = datetime('now');
INSERT INTO _emdash_seo (collection, content_id, seo_title, seo_description, seo_image, seo_canonical, seo_no_index, created_at, updated_at) VALUES ('posts', '01M59K504TRFVT8RE5NX8BJSHF', '【馬來西亞折衷智慧】三大族群如何和平共存？從清真飲食分流看見南洋社會的包容日常', '華人、馬來人與印度人如何在同一塊土地共處？從同一道菜的口味偏好，到美食街餐具分開清洗的細緻界限，深入解密馬來西亞社會在飲食與信仰上最務實動人的「折衷共存哲學」。', NULL, 'https://flavorinsight.com/posts/malaysia-multiracial-code', 0, datetime('now'), datetime('now')) ON CONFLICT (collection, content_id) DO UPDATE SET seo_title = excluded.seo_title, seo_description = excluded.seo_description, seo_canonical = excluded.seo_canonical, updated_at = datetime('now');
INSERT INTO _emdash_seo (collection, content_id, seo_title, seo_description, seo_image, seo_canonical, seo_no_index, created_at, updated_at) VALUES ('posts', '01M59K54C4VDFVFC38HTRN8H38', '【檳城遇見台南】雙城鑊氣對照記：柴燒炒粿條的豬油香，為何讓台南人熱淚盈眶？', '為什麼台南人到了檳城會感到無比親切？深入剖析兩座海港古城的閩南移民脈絡、薄餅豬油渣，以及檳城柴燒炒粿條與台南炒鱔魚意麵那股「生猛鑊氣」背後的人間煙火靈魂。', NULL, 'https://flavorinsight.com/posts/penang-tainan-wok-hei', 0, datetime('now'), datetime('now')) ON CONFLICT (collection, content_id) DO UPDATE SET seo_title = excluded.seo_title, seo_description = excluded.seo_description, seo_canonical = excluded.seo_canonical, updated_at = datetime('now');
INSERT INTO _emdash_seo (collection, content_id, seo_title, seo_description, seo_image, seo_canonical, seo_no_index, created_at, updated_at) VALUES ('posts', '01M59K58NCCYR9YF3WSH6DXDMK', '【巴生肉骨茶溯源】移民社會的混搭美味學：走訪創始人李文地後代與乾式肉骨茶考據', '為什麼大馬小吃總愛把米粉和黃麵混在一起？揭密南洋移民為求生存而生的飲食混搭哲學，並實地造訪巴生肉骨茶創始家族「五月花」，品嚐熱騰騰瓦煲乾肉骨茶的職人底蘊。', NULL, 'https://flavorinsight.com/posts/klang-bak-kut-teh-origins', 0, datetime('now'), datetime('now')) ON CONFLICT (collection, content_id) DO UPDATE SET seo_title = excluded.seo_title, seo_description = excluded.seo_description, seo_canonical = excluded.seo_canonical, updated_at = datetime('now');
INSERT INTO _emdash_seo (collection, content_id, seo_title, seo_description, seo_image, seo_canonical, seo_no_index, created_at, updated_at) VALUES ('posts', '01M59K5CXB1BNS9P1Z01N1HK3V', '【餐飲出海與在地防線】中國連鎖品牌席捲東南亞！檳城為何下令「嚴禁外勞掌廚」守護古早味？', '當中國餐飲品牌大舉進軍東南亞、手搖飲挪用台灣特色，大馬在地老味道如何防守？對比檳城以法規禁外勞掌廚、守護炒粿條等 13 道傳統小吃，與吉隆坡高度商業化的自由競爭，深度剖析東南亞餐飲變局。', NULL, 'https://flavorinsight.com/posts/penang-hawker-ban-street-food', 0, datetime('now'), datetime('now')) ON CONFLICT (collection, content_id) DO UPDATE SET seo_title = excluded.seo_title, seo_description = excluded.seo_description, seo_canonical = excluded.seo_canonical, updated_at = datetime('now');
INSERT INTO _emdash_seo (collection, content_id, seo_title, seo_description, seo_image, seo_canonical, seo_no_index, created_at, updated_at) VALUES ('posts', '01M59K5H2JCZH0RP0E68ASW9ZV', '【南洋靈魂宵夜考】被低估的馬來海南菜：深夜路邊攤 Ramly Burger 與茶餐廳的美味演變', '大馬傳奇街頭宵夜 Ramly Burger 究竟有多誘人？從路邊鐵板煎蛋包肉的罪惡滋味，回溯海南移民如何以西餐廚藝創造出海南雞扒、海南咖啡，寫下跨越族群的南洋味覺傳奇。', NULL, 'https://flavorinsight.com/posts/ramly-burger-hainan-roots', 0, datetime('now'), datetime('now')) ON CONFLICT (collection, content_id) DO UPDATE SET seo_title = excluded.seo_title, seo_description = excluded.seo_description, seo_canonical = excluded.seo_canonical, updated_at = datetime('now');
INSERT INTO _emdash_seo (collection, content_id, seo_title, seo_description, seo_image, seo_canonical, seo_no_index, created_at, updated_at) VALUES ('posts', '01M59K5NA5PHCPA9ERZ0R9SN7D', '【馬來西亞深度全攻略】吉隆坡、檳城、怡保、巴生：3萬字文化脈絡與飲食探索總導覽', '馬來筆記全系列 3 萬字精華總結！收錄吉隆坡捷運輕軌與 TBS 轉運站換乘秘笈，串聯檳城古城、怡保鐵道與巴生常民飲食地圖，獻給熱愛歷史、文化與美食的深度漫遊者。', NULL, 'https://flavorinsight.com/posts/malaysia-deep-travel-guide', 0, datetime('now'), datetime('now')) ON CONFLICT (collection, content_id) DO UPDATE SET seo_title = excluded.seo_title, seo_description = excluded.seo_description, seo_canonical = excluded.seo_canonical, updated_at = datetime('now');
